describe('computeFigureGeometry', () => {
  it.each(KNOWN_FIGURES)('matcher designets figure() for $input', ({ input, expected }) => {
    const actual = computeFigureGeometry(input.weightKg, input.heightCm, input.mood);
    expect(actual).toEqual(expected);
  });

  it('behandler udeladt humør som neutralt', () => {
    expect(computeFigureGeometry(75, 178)).toEqual(computeFigureGeometry(75, 178, 0));
  });

  it('klemmer hovedet mod loftet og dukker sig ved stor højde', () => {
    // The design doesn't clamp the head fully below the ceiling: the overshoot is reduced to 15%.
    // Raw headY = 106 → the top (80) exceeds the ceiling (92) by 12 → 118 − 12 × 0.15 = 116.2.
    const tall = computeFigureGeometry(80, 250);
    expect(tall.headY).toBe(116.2);
    expect(tall.ceilOp).toBe(1);
    expect(tall.headRot).toBe(-26);
    expect(tall.lampRot).toBe(-28);

    const average = computeFigureGeometry(80, 178);
    expect(average.ceilOp).toBe(0);
    expect(average.headRot).toBe(0);
  });

  it('åbner munden og løfter brynene fra 180 kg', () => {
    const light = computeFigureGeometry(150, 178);
    expect(light.smileOp).toBe(1);
    expect(light.browOp).toBe(0);
    expect(light.mouthRx).toBe(0);

    const heavy = computeFigureGeometry(240, 178);
    expect(heavy.smileOp).toBe(0);
    expect(heavy.browOp).toBe(1);
    expect(heavy.mouthRx).toBe(9);
    expect(heavy.mouthRy).toBe(8);
    expect(heavy.browRot).toBe(-18);
    expect(heavy.browRotR).toBe(18);
  });

  it('klemmer bredde og ben fast til designets grænser', () => {
    const tiny = computeFigureGeometry(1, 1);
    expect(tiny.bodyW).toBe(46);
    expect(tiny.legH).toBe(14);
    expect(tiny.bodyH).toBe(34);

    const huge = computeFigureGeometry(1000, 178);
    expect(huge.bodyW).toBe(190);
    expect(huge.bodyRx).toBe(42);
  });
});
